/**
 * Bug Analysis:
 * 1. The `cache` array grows monotonically with every poll interval, never freeing old responses (unbounded memory leak).
 * 2. `setInterval` provides no cancellation token (caller cannot stop polling when component/service unmounts).
 * 3. If a network request takes longer than 5000ms, overlapping asynchronous intervals execute concurrently.
 *
 * Fixed Implementation with bounded buffer and AbortController:
 */
export function startSafePolling(fetchUrl, { intervalMs = 5000, maxBufferSize = 50, onData, signal } = {}) {
  const boundedCache = new Set();
  let timeoutId = null;

  async function poll() {
    if (signal?.aborted) return;
    try {
      const res = await fetch(fetchUrl, { signal });
      if (!res.ok) throw new Error(`HTTP ${res.status}`);
      const data = await res.json();

      if (boundedCache.size >= maxBufferSize) {
        // Evict oldest item to maintain fixed memory boundary
        const oldest = boundedCache.values().next().value;
        boundedCache.delete(oldest);
      }
      boundedCache.add(data);
      onData?.(data);
    } catch (err) {
      if (!signal?.aborted) {
        console.error('Polling error:', err);
      }
    } finally {
      if (!signal?.aborted) {
        timeoutId = setTimeout(poll, intervalMs);
      }
    }
  }

  poll();
  return () => {
    clearTimeout(timeoutId);
  };
}
